def affected(test_list) -> bool:
    rows = list(test_list)
    if not rows:
        return False
    def ev(f, a, b):
        try:
            return ('ok', abs(f(a, b)))
        except Exception as e:
            return ('err', type(e))
    def outcome(r):
        for x in r:
            if x[0] == 'err':
                return ('err', x[1])
        return ('ok', max(x[1] for x in r))
    sub = lambda a, b: a - b
    add = lambda a, b: a + b
    r1 = [ev(sub, a, b) for a, b in rows]
    r2 = [ev(add, a, b) for a, b in rows]
    return outcome(r1) != outcome(r2)
